===== snapshot
{
 "type": "object",
 "additionalProperties": false,
 "required": [
  "schemaVersion",
  "projectId",
  "sourceInventory",
  "resolvedConfigDigest",
  "scopeDigest",
  "vcsDigest"
 ],
 "properties": {
  "schemaVersion": {
   "const": 2
  },
  "projectId": {
   "$ref": "#/$defs/ProjectId"
  },
  "sourceInventory": {
   "$ref": "#/$defs/source-inventory"
  },
  "resolvedConfigDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "bundle": "identity",
     "selector": "#/$defs/semantic-configuration"
    }
   }
  },
  "scopeDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "bundle": "identity",
     "selector": "#/$defs/scope-descriptor"
    }
   }
  },
  "vcsDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "bundle": "identity",
     "selector": "#/$defs/vcs-observation"
    }
   }
  }
 }
}
===== plan
{
