 "properties": {
  "schemaVersion": {
   "const": 2
  },
  "snapshotId": {
   "type": "string",
   "pattern": "^snapshot2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "capabilityManifestId": {
   "$ref": "#/$defs/Hash",
   "x-opensip-digest": {
    "representation": "capability-manifest-id",
    "retention": "derived",
    "derivedFrom": "plan.capabilityManifestBytesDigest"
   }
  },
  "semanticClosures": {
   "type": "array",
   "maxItems": 128,
   "items": {
    "type": "string",
    "pattern": "^closure2:[0-9a-f]{64}(?![\\s\\S])"
   },
   "uniqueItems": true,
   "x-opensip-order": "canonical-set"
  },
  "analysisSpecDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "bundle": "identity",
     "selector": "#/$defs/analysis-spec"
    }
   }
  },
  "resolvedConfigDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "bundle": "identity",
     "selector": "#/$defs/semantic-configuration"
    }
   }
  },
  "nativeContextDigests": {
   "type": "array",
   "maxItems": 128,
   "items": {
    "type": "string",
    "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
    "x-opensip-digest": {
     "representation": "h-identity",
     "domainSet": "native-context"
    }
   },
   "uniqueItems": true,
   "x-opensip-order": "canonical-set"
  },
  "importIds": {
   "type": "array",
   "maxItems": 256,
   "items": {
    "type": "string",
    "pattern": "^import2:[0-9a-f]{64}(?![\\s\\S])"
   },
   "uniqueItems": true,
   "x-opensip-order": "canonical-set"
  },
  "policyDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "document": "workflows/schemas/policy-document.schema.json",
     "selector": "#/$defs/PolicyDocumentV1"
    }
   }
  },
  "waiverDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "document": "workflows/schemas/policy-document.schema.json",
     "selector": "#/$defs/WaiverSetV1"
    }
   }
  },
  "scopeDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "bundle": "identity",
     "selector": "#/$defs/scope-descriptor"
    }
   }
  },
  "budget": {
   "type": "object",
   "additionalProperties": false,
   "required": [
    "unit",
    "limit"
