===== view
{
 "type": "object",
 "additionalProperties": false,
 "required": [
  "schemaVersion",
  "planId",
  "scopeIds",
  "facts",
  "coverageIds",
  "producerClosure",
  "schemaDigests"
 ],
 "properties": {
  "schemaVersion": {
   "const": 2
  },
  "planId": {
   "type": "string",
   "pattern": "^plan2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "scopeIds": {
   "type": "array",
   "maxItems": 100000,
   "items": {
    "type": "string",
    "pattern": "^scope2:[0-9a-f]{64}(?![\\s\\S])"
   },
   "uniqueItems": true,
   "x-opensip-order": "canonical-set"
  },
  "facts": {
   "type": "array",
   "maxItems": 100000,
   "uniqueItems": true,
   "items": {
    "type": "string",
    "pattern": "^fact2:[0-9a-f]{64}(?![\\s\\S])"
   },
   "x-opensip-order": "canonical-set"
  },
  "coverageIds": {
   "type": "array",
   "maxItems": 100000,
   "items": {
    "type": "string",
    "pattern": "^coverage2:[0-9a-f]{64}(?![\\s\\S])"
   },
   "uniqueItems": true,
   "x-opensip-order": "canonical-set"
  },
  "producerClosure": {
   "type": "string",
   "pattern": "^closure2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "schemaDigests": {
   "type": "array",
   "maxItems": 128,
   "items": {
    "type": "string",
    "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
    "x-opensip-digest": {
     "representation": "raw-artifact",
     "artifact": "the exact complete registered schema document bytes of a schema this view admitted"
    }
   },
   "uniqueItems": true,
   "x-opensip-order": "canonical-set"
  }
 }
}
===== coverage
{
 "type": "object",
 "additionalProperties": false,
 "required": [
  "schemaVersion",
  "scopeId",
  "payloadSchemaDigest",
  "payloadDigest"
 ],
 "properties": {
  "schemaVersion": {
   "const": 2
  },
  "scopeId": {
   "type": "string",
   "pattern": "^scope2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "payloadSchemaDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "raw-artifact",
    "artifact": "the exact full bytes of the registered Coverage payload schema document for the payload schemaVersion"
   }
  },
  "payloadDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "payloadClass": "coverage",
     "keyedBy": [
      "payload.schemaVersion"
     ],
     "schemaDigestField": "payloadSchemaDigest"
    }
   }
  }
 }
}
===== fact
{
 "type": "object",
 "additionalProperties": false,
 "required": [
  "schemaVersion",
  "snapshotId",
  "relation",
  "resolution",
  "sourceUniverse",
  "targetUniverse",
  "producerClosure",
  "payloadSchemaDigest",
  "payloadDigest",
  "anchors",
  "confidenceMillionths"
 ],
 "properties": {
  "schemaVersion": {
   "const": 2
  },
  "snapshotId": {
   "type": "string",
   "pattern": "^snapshot2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "relation": {
   "type": "string",
   "minLength": 1,
   "maxLength": 4096
  },
  "resolution": {
   "type": "string",
   "minLength": 1,
   "maxLength": 4096
  },
  "sourceUniverse": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "h-identity",
    "domainSet": "native-semantic-universe"
   }
  },
  "targetUniverse": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "h-identity",
    "domainSet": "native-semantic-universe"
   }
  },
  "producerClosure": {
   "type": "string",
   "pattern": "^closure2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "payloadSchemaDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "raw-artifact",
    "artifact": "the exact full bytes of foundation/relation-payload-schemas.v2.json, the registered relation payload schema document"
   }
  },
  "payloadDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "payloadClass": "relation",
     "keyedBy": [
      "relation"
     ],
     "schemaDigestField": "payloadSchemaDigest"
    }
   }
  },
  "anchors": {
   "type": "array",
   "maxItems": 100000,
   "uniqueItems": true,
   "items": {
    "type": "object",
    "additionalProperties": false,
    "required": [
     "path",
     "blobDigest",
     "startByte",
     "endByte"
    ],
    "properties": {
     "path": {
      "type": "string",
      "minLength": 1,
      "maxLength": 4096
     },
     "blobDigest": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
      "x-opensip-digest": {
       "representation": "raw-artifact",
       "artifact": "the exact retained source blob bytes named by path in the snapshot inventory"
      }
     },
     "startByte": {
      "type": "integer",
      "minimum": 0,
      "maximum": 18446744073709551615
     },
     "endByte": {
      "type": "integer",
      "minimum": 0,
      "maximum": 18446744073709551615
     }
    }
   },
   "x-opensip-order": "canonical-set"
  },
  "confidenceMillionths": {
   "type": "integer",
   "minimum": 0,
   "maximum": 1000000
  }
 }
}
===== subject-scope
{
 "type": "object",
 "additionalProperties": false,
 "required": [
  "schemaVersion",
  "snapshotId",
  "sourceUniverse",
  "targetUniverse",
  "relation",
  "resolution",
  "enumeratorClosure",
  "subjects"
 ],
 "properties": {
  "schemaVersion": {
   "const": 2
  },
  "snapshotId": {
   "type": "string",
   "pattern": "^snapshot2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "sourceUniverse": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "h-identity",
    "domainSet": "native-semantic-universe"
   }
  },
  "targetUniverse": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "h-identity",
    "domainSet": "native-semantic-universe"
   }
  },
  "relation": {
   "type": "string",
   "minLength": 1,
   "maxLength": 4096
  },
  "resolution": {
   "type": "string",
   "minLength": 1,
   "maxLength": 4096
  },
  "enumeratorClosure": {
   "type": "string",
   "pattern": "^closure2:[0-9a-f]{64}(?![\\s\\S])",
   "description": "The Plan-selected closure that enumerated this scope. Its kind must be 'provider': enumeration is a native provider act, and no 'enumerator' kind is minted for it. The closure must also be a member of plan.semanticClosures, so the enumerator is one the Plan selected."
  },
  "subjects": {
   "type": "array",
   "maxItems": 100000,
   "items": {
    "type": "string",
    "minLength": 1,
    "maxLength": 4096
   },
   "uniqueItems": true,
   "x-opensip-order": "canonical-set"
  }
 }
}
